// Run against the game/ directory generated by this comparison's build.cjs.
import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { performance } from 'node:perf_hooks';
import { pathToFileURL } from 'node:url';

const [root, out, orderFlag] = process.argv.slice(2);
if (!root || !out) throw new Error('Usage: node performance-helper.mjs GAME_DIR RESULT.json');
const at = name => path.resolve(root, name);
const importNative = name => import(pathToFileURL(at(name)));
const require = createRequire(import.meta.url);
const fixture = JSON.parse(fs.readFileSync(new URL('./geometry-fixture.json', import.meta.url)));
const { selectRecoveredScene } = await importNative('home-production-manifest.mjs');
const { createRecoveredNavigation } = await importNative('home-recovered-navigation-finish.mjs');
const { extendVisibleGroundNavigation } = await importNative('home-visible-ground-navigation-finish.mjs');
const { insidePolygon } = await importNative('home-art-navigation-finish.mjs');
const { residents, nativeStage, stageToCss, cover } = fixture;
const sx = stageToCss.scaleX, sy = stageToCss.scaleY;
const spec = selectRecoveredScene('forest');
const legacy = createRecoveredNavigation(spec, nativeStage, nativeStage, { stableGrid: true });
const navigation = extendVisibleGroundNavigation(legacy, {
  spec, cover, stage: { left: stageToCss.left / sx, top: stageToCss.top / sy },
  presentation: { x: 0, y: 0, scaleX: sx, scaleY: sy },
});
const polygons = spec.foreground.map(poly => poly.map(([u, v]) => [
  (cover.left + u * cover.width - stageToCss.left) / sx,
  (cover.top + v * cover.height - stageToCss.top) / sy,
]));
const byKey = new Map(residents.map(r => [r.key, r]));
const people = residents.map(({ key, x, y, w, h }) => ({ key, kind: key.split(':')[0], x, y, w, h }));

function mask(resident, p) {
  for (const dx of [-.3 * resident.w, 0, .3 * resident.w]) {
    for (const dy of [.22 * resident.h, .5 * resident.h, .8 * resident.h]) {
      if (polygons.some(poly => insidePolygon(p.x + dx, p.y - dy, poly))) return false;
    }
  }
  return true;
}

function advance(api, target) {
  const model = api.createModel({random: () => .5});
  let placing = true;
  const scene = {
    width: nativeStage.width, height: nativeStage.height, groundTop: 24, region: 'forest',
    navigation: {...navigation, initialPoint: i => ({x:residents[i].x, y:residents[i].y})},
    referenceBounds: actor => api.bounds(actor, {...scene, actorBounds:null}),
    actorBounds: actor => byKey.get(actor.key).bounds,
    planVisibility: actor => p => mask(actor, p),
    visible(p, actor) {
      const from = byKey.get(actor.key);
      return placing ? Math.hypot(from.x - p.x, from.y - p.y) < 1e-7 : mask(actor, p);
    }
  };
  model.sync(people, scene);
  placing = false;
  const feet = () => model.snapshot().map(a => [a.x, a.y]);
  assert.deepEqual(feet(), residents.map(r => [r.x, r.y]));
  const goal = {x:target.releaseNative[0], y:target.releaseNative[1]};
  model.select(target.key);
  const begin = performance.now();
  model.move(target.key, goal, 'drag', {pointerDrop:true});
  const releaseMs = performance.now() - begin;
  assert.deepEqual(feet(), residents.map(r => [r.x, r.y]));
  const steps = [];
  let refreshMs;
  for (let i = 0; i < 245; i++) {
    if (i === 6) {
      const before = feet(), t = performance.now();
      model.sync(people, scene);
      refreshMs = performance.now() - t;
      assert.deepEqual(feet(), before);
    }
    const t = performance.now();
    model.step(.05, {autonomy:false});
    steps.push(performance.now() - t);
  }
  const actors = model.snapshot(), end = actors.find(a => a.key === target.key);
  const helpers = actors.filter(a => a.source === 'yield').map(a => a.key);
  const errorCss = Math.hypot((goal.x - end.x) * sx, (goal.y - end.y) * sy);
  return {releaseMs, refreshMs, errorCss, helpers, steps};
}

const rows = [], builds = {};
const forward = [[5,['v5','v6','v7']],[24,['v7','v6','v5']]];
const order = orderFlag === '--reverse' ? forward.toReversed().map(([i, arms]) => [i, arms.toReversed()]) : forward;
for (const [index, arms] of order) {
  for (const arm of arms) {
    const file = at('home-production-model-mobility-' + arm + '.js');
    builds[arm] = crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
    const sample = advance(require(file), residents[index]);
    if (arm === 'v7') {
      assert.equal(sample.helpers.length, 2);
      assert.ok(sample.errorCss < 8);
    }
    rows.push({arm, target:residents[index].key, ...sample});
  }
}
fs.writeFileSync(out, JSON.stringify({node:process.version, builds, rows}) + '\n');
